                content: `import { RestApi } from '@servicenow/sdk/core'
RestApi({
    $id: Now.ID['rest0'],
    name: 'customAPI',
    serviceId: 'custom_api',
    routes: [
        {
            $id: Now.ID['route0'],
            script: 'gs.info("simple script");',
            parameters: [{ $id:  Now.ID['parameter0'],  name: 'n_param' }],
            headers: [{ $id:  Now.ID['header0'],  name: 'n_header' }],
            version: 1
        },
    ],
    versions: [{
        $id: Now.ID['version0'],
        version: 1
    }]
})`,
